package com.example.payments;

import org.apache.commons.text.StringSubstitutor;

import java.util.Map;

/** Renders payment notification templates for the settlement batch job. */
public class PaymentService {

    private final Map<String, String> templateValues;

    public PaymentService(Map<String, String> templateValues) {
        this.templateValues = templateValues;
    }

    public String renderNotification(String template) {
        StringSubstitutor substitutor = new StringSubstitutor(templateValues);
        return substitutor.replace(template);
    }
}

