package com.example.payments;

import java.lang.reflect.Method;

/** Loads a pluggable settlement strategy named in application.yml via reflection. */
public class ReflectiveConfigLoader {

    public Object loadStrategy(String className, String methodName) throws Exception {
        Class<?> clazz = Class.forName(className);
        Method factory = clazz.getMethod(methodName);
        return factory.invoke(null);
    }
}
